// Guard rails before anything sends.
// Two entry points: the n8n form, and the Dispo Deal Console (JSON body).
// The console's own two-step "Yes - send to N buyers now" confirmation is the
// equivalent of typing SEND, so it is not asked for it twice.
let form = null, con = null;
try { form = $('Blast Form').first().json; } catch (e) {}
try { const c = $('Console Send').first().json; con = (c && c.body) ? c.body : null; } catch (e) {}

const search = $input.first().json;
const norm = (s) => (s || '').toLowerCase().replace(/\s+/g, ' ').trim();

// Teasers arrive keyed on the LABEL the review page showed, so this map is the
// wire contract with the console. The old label stays as an alias: a page a
// dispo agent opened before the rename is still sitting in their browser, and
// dropping it would silently send that segment no teaser at all.
const SEG_BY_LABEL = {
  'warm list': 'warm',
  'investorbase matched': 'geo_cold',
  'geo-matched cold': 'geo_cold',   // legacy label, pre 2026-08-19
  'general cold': 'general_cold'
};

let address, teaser, teasers, enabled, editedPost, limit, confirmed;
// Buyer types the dispo manager held on the review page. Absent for the
// legacy form path, which has no such control - an empty list holds nobody.
let typesHeld = [], tiersHeld = [], testOnly = false, includeUnscrubbed = false;
// Default TRUE: only an explicit false from the review page drops the line.
let includeOptOut = true;

if (con) {
  address = String(con.address || '').trim();
  teasers = {};
  enabled = {};
  const t = con.teasers || {}, en = con.segmentsEnabled || {};
  typesHeld = Array.isArray(con.typesHeld) ? con.typesHeld.map(String) : [];
  tiersHeld = Array.isArray(con.tiersHeld) ? con.tiersHeld.map(String) : [];
  testOnly  = con.testOnly === true;
  // Deliberate, per-blast, and permanently recorded in the execution log.
  includeUnscrubbed = con.includeUnscrubbed === true;
  includeOptOut = con.includeOptOut !== false;
  for (const label of Object.keys(t)) {
    const k = SEG_BY_LABEL[norm(label)];
    if (k) teasers[k] = String(t[label] || '').trim();
  }
  for (const label of Object.keys(en)) {
    const k = SEG_BY_LABEL[norm(label)];
    if (k) enabled[k] = en[label] === true;
  }
  editedPost = String(con.smsPost || '').trim();
  limit = null;
  confirmed = true;
  // Representative teaser for the record; each buyer still gets their own.
  teaser = teasers.warm || teasers.geo_cold || teasers.general_cold || '';
} else {
  form = form || {};
  address = String(form['Property Address'] || '').trim();
  teaser = String(form['Teaser to send'] || '').trim();
  // The form has one box, so every segment gets the same text.
  teasers = { warm: teaser, geo_cold: teaser, general_cold: teaser };
  enabled = { warm: true, geo_cold: true, general_cold: true };
  editedPost = String(form['Replace SMS post (optional)'] || '').trim();
  const limitRaw = form['Limit (optional)'];
  limit = (limitRaw === '' || limitRaw == null) ? null : Number(limitRaw);
  confirmed = String(form['Type SEND to confirm'] || '').trim().toUpperCase() === 'SEND';
}

const target = norm(address);
const rec = (search.records || []).find(r => norm(r.properties?.prop_address) === target);

const anyOn = Object.keys(enabled).some(k => enabled[k]);
const anyText = Object.keys(teasers).some(k => enabled[k] && teasers[k]);

let abort = null;
if (!confirmed) abort = 'Confirmation text was not exactly SEND. Nothing was sent.';
else if (!rec) abort = 'No deal found at that address. It must match the intake address exactly.';
else if (!anyOn) abort = 'Every segment was held back. Nothing was sent.';
else if (!anyText) abort = 'Every segment that was switched on had an empty teaser. Nothing was sent.';

return [{ json: {
  abort,
  viaConsole: !!con,
  recordId: rec ? rec.id : null,
  address: rec ? rec.properties.prop_address : address,
  teaser,
  teasers,
  enabled,
  typesHeld,
  tiersHeld,
  testOnly,
  includeUnscrubbed,
  includeOptOut,
  teaserEdited: !!(rec && teaser && teaser !== (rec.properties.prop_teaser_sms || '')),
  editedPost,
  alreadySent: rec ? (rec.properties.prop_blast_status === 'teasersent') : false,
  props: rec ? rec.properties : {},
  limit
} }];

// Re-run the SAME exclusion logic as intake. Deliberately re-evaluated at send
// time rather than trusting the list from intake: an excl_ rule or a DNC may
// have been set in between, and the send is the moment that must be correct.
const pages = $input.all();
const pool = pages.flatMap(p => p.json.contacts || []);
const deal = $('Guard Rails').first().json;
const p = deal.props;

const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID = {};
for (const d of defs) ID[d.name] = d.id;
const cf = (c, name) => {
  const id = ID[name];
  const hit = (c.customFields || []).find(x => x.id === id || x.id === name || x.key === name);
  if (!hit) return null;
  return hit.value !== undefined ? hit.value : (hit.fieldValue !== undefined ? hit.fieldValue : null);
};
const arr = (v) => v == null ? [] : (Array.isArray(v) ? v : String(v).split(';').map(s => s.trim()).filter(Boolean));
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// GHL stores a picklist KEY on the record ('2to4unit') but the buyer's field
// holds the LABEL ('2-4 Unit'), and norm() maps those to '2to4unit' and
// '24unit' - which never match. A buyer who told us 'no 2-4 units' was being
// blasted 2-4 units. Invisible until now because every deal has been an SFR.
const TYPE_ALIAS = { '2to4unit': '24unit', '5plusunit': '5unit',
                     'manufacturedhome': 'manufactured', 'mfg': 'manufactured' };
const canonType = (s) => { const t = norm(s); return TYPE_ALIAS[t] || t; };
const n = (v) => (v == null || v === '') ? null : Number(v);


// Address comparison for deal-scoping.
//
// 2026-08-25: comparing the WHOLE address was wrong. InvestorBase stamped
// "1125 Highview Rd, Lantana, FL 33462" while the deal was entered as
// "1125 Highview Rd Lake Worth FL 33462". Both are correct - ZIP 33462
// straddles a municipal line, so USPS says Lake Worth and the municipality is
// Lantana - but neither string contains the other, so all 76 buyers
// InvestorBase pulled for this address were counted as General cold.
//
// Compare what actually identifies a property instead: the STREET (house
// number + name, suffix canonicalised so "Rd" == "Road", ordinals reduced so
// "58 St" == "58th St") and the ZIP when both sides carry one. City and state
// are ignored on purpose - they are the parts the two systems disagree about.
//
// When either side has no parseable street - InvestorBase pulls like
// "4200 Dispo" carry no suffix - it falls back to the old containment test
// rather than silently dropping the buyer.
const ST_SUFFIX = {
  st: 'st', street: 'st', rd: 'rd', road: 'rd', ave: 'ave', av: 'ave',
  avenue: 'ave', dr: 'dr', drive: 'dr', ln: 'ln', lane: 'ln', ct: 'ct',
  court: 'ct', blvd: 'blvd', boulevard: 'blvd', ter: 'ter', terr: 'ter',
  terrace: 'ter', pl: 'pl', place: 'pl', way: 'way', cir: 'cir',
  circle: 'cir', pkwy: 'pkwy', parkway: 'pkwy', hwy: 'hwy', highway: 'hwy',
  trl: 'trl', trail: 'trl', loop: 'loop', run: 'run', path: 'path',
  sq: 'sq', square: 'sq', cv: 'cv', cove: 'cv', pt: 'pt', point: 'pt',
  xing: 'xing', crossing: 'xing', bnd: 'bnd', bend: 'bnd',
};
const DIRECTION = {
  north: 'n', south: 's', east: 'e', west: 'w', northeast: 'ne',
  northwest: 'nw', southeast: 'se', southwest: 'sw',
};
// Canonical token string: lowercase words, single spaces, street ordinals cut
// to digits, directionals abbreviated. Keeping the SPACES is what makes the
// street and the ZIP recoverable below - the old version flattened them away.
const normAddr = (s) => String(s == null ? '' : s).toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean)
  .map((t) => {
    const ord = t.match(/^(\d+)(?:st|nd|rd|th)$/);
    return ord ? ord[1] : (DIRECTION[t] || t);
  }).join(' ');
const addrParts = (norm) => {
  const toks = String(norm || '').split(' ').filter(Boolean);
  // The ZIP is the LAST five-digit token and never the first: a house number
  // like "10250" is five digits too.
  let zip = '';
  for (let i = 1; i < toks.length; i++) if (/^\d{5}$/.test(toks[i])) zip = toks[i];
  let street = '';
  if (toks.length && /^\d/.test(toks[0])) {
    const out = [toks[0]];
    for (let i = 1; i < toks.length; i++) {
      const suf = ST_SUFFIX[toks[i]];
      if (suf) { out.push(suf); street = out.join(''); break; }
      out.push(toks[i]);
    }
  }
  return { street: street, zip: zip, flat: toks.join('') };
};
const addrMatch = (a, b) => {
  if (!a || !b) return false;
  const pa = addrParts(a);
  const pb = addrParts(b);
  if (pa.street && pb.street) {
    if (pa.street !== pb.street) return false;
    // The same street name exists in many ZIPs. Demand a ZIP match only when
    // both sides actually carry one, so a bare "1125 Highview Rd" still counts.
    if (pa.zip && pb.zip) return pa.zip === pb.zip;
    return true;
  }
  return pa.flat === pb.flat
    || pa.flat.indexOf(pb.flat) !== -1
    || pb.flat.indexOf(pa.flat) !== -1;
};
const dealAddr = normAddr(p.prop_address);
const dealCounty = norm(p.prop_county);
const dealHood = norm(p.prop_neighborhood || '');
const dealType = canonType(p.prop_type);
const asking = n(p.prop_asking_price);
const sqft = n(p.prop_sqft);

// The merge token Claude is told to write. Assembled from pieces so the raw
// '{{' never appears in this file either - see the note at row.smsBody.
const TOKEN = '{' + '{first_name}' + '}';
// The exact opt-out wording. Fixed, so every cold text carries the same
// auditable sentence and the Florida FTSA text safe harbour actually applies.
const OPT_OUT_LINE = 'Reply STOP to opt out.';
const send = [], skipped = [];

for (const c of pool) {
  const name = [c.firstName, c.lastName].filter(Boolean).join(' ') || c.contactName || '(no name)';
  const row = { id: c.id, name, phone: c.phone || null, tier: cf(c, 'buy_tier') || '(none)', segment: '',
                priorDealsSent: Number(cf(c, 'buy_deals_sent') || 0) || 0,
                priorFirstContacted: cf(c, 'buy_first_contacted') || '' };

  const rt = arr(cf(c, 'record_type')).map(norm);
  if (!rt.includes('buyer')) continue;

  const status = norm(cf(c, 'buy_status'));
  if (status === 'dnc' || status === 'blacklist') { skipped.push({ ...row, why: 'buy_status=' + status }); continue; }
  if (c.dnd === true) { skipped.push({ ...row, why: 'contact DND is on' }); continue; }
  if (!c.phone) { skipped.push({ ...row, why: 'no phone' }); continue; }
  // ---- VETTING GATE ----
  // InvestorLift inquiries arrive as buy_vetted=Unvetted because some of them
  // are competing wholesalers fishing for the address, not buyers. A dispo
  // agent flips one field - buy_vetted=Vetted - and they blast normally
  // forever after. Rejected means confirmed snake: held permanently, kept on
  // file so we never have to re-learn who they are.
  // BLANK IS BLASTABLE. The 121 master buyers and every InvestorBase import
  // have no value here and must not be affected.
  const vetted = norm(cf(c, 'buy_vetted'));
  if (vetted === 'unvetted') { skipped.push({ ...row, why: 'not vetted yet - dispo must set buy_vetted=Vetted' }); continue; }
  if (vetted === 'rejected') { skipped.push({ ...row, why: 'buy_vetted=Rejected (known snake)' }); continue; }

  const why = [];
  if (norm(cf(c, 'excl_all_blasts')) === 'yes') why.push('held from all blasts');

  // ---- InvestorBase buyers are DEAL-SCOPED ----
  // IB returns buyers within ~2 miles of one subject property. They were never
  // a general buyer list, so they are only eligible for the deal they were
  // pulled for. Master-list buyers (BH Main / Referral) get everything.
  const srcNorm = arr(cf(c, 'buy_source')).map(norm);
  // SEGMENT, do not exclude. Source decides the SCRIPT, not eligibility.
  // An InvestorBase buyer sourced for another property is still a real cash
  // buyer in this county - excluding them would throw away the database the
  // imports exist to build.

  // ---- DNC + LITIGATOR SCRUB ----
  // Two separate things, and both are hard stops.
  //
  // A scrub HIT is never sendable, whatever the source. A TCPA litigator on a
  // purchased list is someone whose business is collecting statutory damages,
  // and Florida's FTSA carries a private right of action at $500 a text.
  const scrub = norm(cf(c, 'buy_scrub_result'));
  if (scrub === 'dnc' || scrub === 'litigator') {
    skipped.push({ ...row, why: 'scrub hit: ' + scrub });
    continue;
  }

  // A buyer we PURCHASED and have no relationship with must be scrubbed before
  // they are ever texted. Someone on the master list opted in to hearing from
  // us; a skip-traced stranger from InvestorBase did not, and is exactly who
  // the federal and Florida registries exist to protect.
  // The override covers UNSCRUBBED only. A confirmed DNC or litigator hit is
  // handled above and is never releasable - no checkbox reaches it.
  const onMasterList = srcNorm.includes('bhmain') || srcNorm.includes('referral');
  if (!onMasterList && scrub !== 'clean' && deal.includeUnscrubbed !== true) {
    skipped.push({ ...row, why: 'not scrubbed - purchased list, needs a DNC + litigator check' });
    continue;
  }
  const pulledLines = String(cf(c, 'buy_ib_property') || '')
    .split(/[;\n]/).map(s => normAddr(s)).filter(Boolean);
  const geoMatched = pulledLines.some(a => addrMatch(a, dealAddr));
  // The 'Inquired' segment is gone: it only ever meant an InvestorLift buyer
  // who raised a hand on THIS property, and InvestorLift is not wired up.
  // Jorge, 2026-08-20: 'remove inquired across the board... im not going to
  // wire up investorlift for now.' If it comes back, this is where it starts.
  let segment;
  if (srcNorm.includes('bhmain') || srcNorm.includes('referral')) segment = 'warm';
  else if (geoMatched) segment = 'geo_cold';
  else segment = 'general_cold';

  const bp = n(cf(c, 'excl_below_price')); if (bp && asking && asking < bp) why.push('below their price floor');
  const ap = n(cf(c, 'excl_above_price')); if (ap && asking && asking > ap) why.push('above their price ceiling');
  const bs = n(cf(c, 'excl_below_sqft')); if (bs && sqft && sqft < bs) why.push('below their sqft floor');
  const et = arr(cf(c, 'excl_prop_types')).map(canonType); if (et.length && dealType && et.includes(dealType)) why.push('excludes this property type');
  const oc = arr(cf(c, 'excl_outside_counties')).map(norm); if (oc.length && dealCounty && !oc.includes(dealCounty)) why.push('outside their counties');
  const oh = arr(cf(c, 'excl_outside_neighborhoods')).map(norm); if (oh.length && dealHood && !oh.includes(dealHood)) why.push('outside their sub-markets');

  if (why.length) { skipped.push({ ...row, why: why.join('; ') }); continue; }
  row.segment = segment;

  // A segment switched off in the console is held back, and says so.
  if (deal.enabled && deal.enabled[segment] === false) {
    skipped.push({ ...row, why: 'segment held back for this blast' });
    continue;
  }
  // No approved text for this segment means no send. Never silently fall
  // back to another segment's script - the wrong opener to a cold buyer is
  // worse than no text at all.
  // ---- TEST SEND: a WHITELIST, checked before every other rule ----
  // When the dispo manager flips Test send, exactly one thing is true: only
  // buy_type TEST goes out. Deliberately not expressed as "hold everything
  // else" - that would depend on eight checkboxes all being right, and one
  // missed chip is a text to the whole database.
  const testSend = deal.testOnly === true;
  if (testSend) {
    const mineT = arr(cf(c, 'buy_type')).map(norm);
    if (mineT.indexOf('test') === -1) {
      skipped.push({ ...row, why: 'TEST SEND - only buy_type TEST receives this blast' });
      continue;
    }
  }

  // ---- PER-BLAST HOLD BY BUYER TYPE ----
  // Chosen on the review page, travels with the send. This is NOT an exclusion
  // and nothing is written to buy_type: a JV partner is a real buyer, just not
  // the audience for an end-buyer blast. Re-checked here rather than trusted
  // from intake because the list is rebuilt at send time.
  const heldTypes = (!testSend && Array.isArray(deal.typesHeld)) ? deal.typesHeld.map(norm) : [];
  if (heldTypes.length) {
    const mine = arr(cf(c, 'buy_type'));
    const hit = mine.filter(t => heldTypes.indexOf(norm(t)) !== -1);
    if (hit.length) {
      skipped.push({ ...row, why: 'buy_type ' + hit.join('/') + ' held back for this blast' });
      continue;
    }
  }

  // Same idea by tier. The usual case is holding VIPs: they get a phone call
  // from a partner, not a mass text. buy_tier is never written here either.
  const heldTiers = (!testSend && Array.isArray(deal.tiersHeld)) ? deal.tiersHeld.map(norm) : [];
  if (heldTiers.length) {
    const myTier = cf(c, 'buy_tier');
    if (myTier && heldTiers.indexOf(norm(myTier)) !== -1) {
      skipped.push({ ...row, why: 'tier ' + myTier + ' held back for this blast' });
      continue;
    }
  }


  // ---- WHICH NUMBER WE TEXT FROM ----
  // Buyers save our number. Texting an existing buyer from a different one
  // makes us a stranger again in a brand new thread, and carriers score
  // sender->recipient pairs, so a settled pairing also looks less like spam.
  // So: STICKY first, rotate only for someone we have never texted.
  //
  // VIPs and JV partners are pinned to one number that never carries cold
  // volume, so the relationships we care most about sit on a clean line.
  // Jorge, 2026-08-19: 'JVs and VIPs should just get one number from us'.
  const RELATIONSHIP_NUMBER = '+17868414589';   // 'Buyer Number'
  const ROTATION = ['+17864345766', '+17867306407', '+19543292967'];
  // The main line (+17869827813) is deliberately NOT here - it is the seller
  // side's number and must never carry a buyer blast.
  const ALL_NUMBERS = [RELATIONSHIP_NUMBER].concat(ROTATION);

  const storedFrom = String(cf(c, 'buy_from_number') || '').trim();
  // A number that has been retired is worse than none: the send would fail or
  // come from a line nobody owns. Fall through to a fresh assignment.
  const sticky = ALL_NUMBERS.indexOf(storedFrom) !== -1 ? storedFrom : '';

  const myTypes = arr(cf(c, 'buy_type')).map(norm);
  const relationship = norm(cf(c, 'buy_tier')) === 'vip' || myTypes.indexOf('jv') !== -1;

  if (sticky) {
    row.fromNumber = sticky;
  } else if (relationship) {
    row.fromNumber = RELATIONSHIP_NUMBER;
  } else {
    // Hash of their phone, not a counter: deterministic, evenly spread, and
    // two blasts running at once cannot hand out the same slot twice.
    const d = String(row.phone || '').replace(/[^0-9]/g, '');
    let h = 0;
    for (let i = 0; i < d.length; i++) h = (h * 31 + d.charCodeAt(i)) % 1000003;
    row.fromNumber = ROTATION[h % ROTATION.length];
  }
  // Only stamp the field when it was not already set - it is set-once.
  row.fromNumberIsNew = !sticky;
  row.teaser = (deal.teasers && deal.teasers[segment]) || '';
  if (!row.teaser) {
    skipped.push({ ...row, why: 'no approved teaser for the ' + segment + ' segment' });
    continue;
  }

  // Build the EXACT string that will be texted, here in code.
  // It used to be assembled inside the HTTP node's expression, which meant a
  // literal '{{first_name}}' sat nested inside n8n's own {{ }} template. n8n
  // parsed the inner braces as the end of its expression and every send died
  // with a bare "invalid syntax". Nothing that ships to a buyer should be
  // assembled in an expression field.
  const firstName = String(row.name || '').trim().split(' ')[0] || 'there';
  let body = String(row.teaser).split(TOKEN).join(firstName);

  // ---- OPT-OUT LINE ----
  // Appended HERE, in code, as a fixed string - not written by the model.
  // Florida's FTSA gives a safe harbour for texts the recipient can opt out of
  // by replying STOP, and a safe harbour you rely on cannot be a sentence an
  // LLM rephrases per deal. One exact wording, every time, auditable.
  //
  // Applied to everyone NOT on our master list: anyone we bought or who found
  // us through InvestorBase or InvestorLift, warm-scripted or not. Jorge,
  // 2026-08-19: 'all investor base outreach that's not part of bh main needs
  // the reply to stop'.
  // RULE 1, and it is not a toggle: a BH Main or Referral buyer NEVER gets the
  // opt-out line. They are on our master list because they asked to be, and
  // 'Reply STOP to opt out' to someone Andrew spoke to last week reads as a
  // form letter from a stranger. Jorge, 2026-08-20: 'BH Main never gets reply
  // stop to opt out'. No per-blast setting can turn this off.
  const optOutForbidden = onMasterList;

  // RULE 2, and it IS a toggle: for everyone else it is on unless the review
  // page explicitly turned it off. ABSENT means include - a payload from an
  // older page or a missing field can never silently drop it.
  const wantOptOut = deal.includeOptOut !== false;

  const alreadySaysStop = body.toLowerCase().indexOf('stop') !== -1;
  if (!optOutForbidden && wantOptOut && !alreadySaysStop) {
    body = body.replace(/\s+$/, '') + ' ' + OPT_OUT_LINE;
  }
  row.smsBody = body;
  row.hasOptOut = body.toLowerCase().indexOf('stop') !== -1;

  send.push(row);
}


// ---- Deduplicate on phone. One human, one text. ----
// Records are joined on phone at IMPORT time, so duplicates here mean two
// contact records carrying the SAME number - a merge that never happened, a
// manual entry, a re-import under a second record. Whatever the cause, the
// buyer must not receive the same deal twice, and definitely not once warm and
// once cold.
const TIER_RANK = { VIP: 0, A: 1, B: 2, C: 3 };
const SEG_RANK = { warm: 0, geo_cold: 1, general_cold: 2 };
const phoneKey = (p) => String(p == null ? '' : p).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
// Keep the record most likely to be the curated one: best tier, then warmest
// segment, then whichever was already ahead in the list.
const betterOf = (a, b) => {
  const ta = TIER_RANK[a.tier] == null ? 9 : TIER_RANK[a.tier];
  const tb = TIER_RANK[b.tier] == null ? 9 : TIER_RANK[b.tier];
  if (ta !== tb) return ta < tb ? a : b;
  const sa = SEG_RANK[a.segment] == null ? 9 : SEG_RANK[a.segment];
  const sb = SEG_RANK[b.segment] == null ? 9 : SEG_RANK[b.segment];
  if (sa !== sb) return sa < sb ? a : b;
  return a;
};

const byPhone = new Map();
const dupes = [];
for (const b of send) {
  const k = phoneKey(b.phone);
  if (!k) continue;
  const prev = byPhone.get(k);
  if (!prev) { byPhone.set(k, b); continue; }
  const keep = betterOf(prev, b);
  byPhone.set(k, keep);
  dupes.push(keep === prev ? b : prev);
}
const kept = new Set(Array.from(byPhone.values()));
const uniq = send.filter(b => kept.has(b));
for (const d of dupes) {
  const winner = byPhone.get(phoneKey(d.phone));
  skipped.push(Object.assign({}, d, {
    why: 'duplicate phone - already texting ' + (winner ? winner.name : 'another buyer') + ' on this number'
  }));
}
send.length = 0;
for (const b of uniq) send.push(b);

const rank = { VIP: 0, A: 1, B: 2, C: 3 };
send.sort((a, b) => (rank[a.tier] ?? 9) - (rank[b.tier] ?? 9));

const limited = deal.limit ? send.slice(0, deal.limit) : send;
const heldByLimit = send.length - limited.length;

if (!limited.length) {
  return [{ json: { _none: true, address: deal.address, recordId: deal.recordId,
                    eligible: 0, skipped, heldByLimit } }];
}

// One item per recipient - the send node runs once per item.
return limited.map(b => ({ json: {
  contactId: b.id,
  name: b.name,
  phone: b.phone,
  tier: b.tier,
  segment: b.segment,
  teaser: b.teaser,
  // The finished, personalised text. This projection is explicit, so anything
  // added to the row above has to be added HERE too or it silently vanishes
  // and the send node posts an empty message.
  smsBody: b.smsBody,
  fromNumber: b.fromNumber,
  fromNumberIsNew: b.fromNumberIsNew,
  priorDealsSent: b.priorDealsSent,
  priorFirstContacted: b.priorFirstContacted,
  address: deal.address,
  recordId: deal.recordId,
  _stats: { eligible: send.length, sending: limited.length, heldByLimit, skipped }
} }));

const results = $input.all();
const recips = $('Build Recipient List').all();
const stats = (recips[0] && recips[0].json._stats) || { eligible: 0, sending: 0, heldByLimit: 0, skipped: [] };

const sent = [], failed = [];
for (let i = 0; i < results.length; i++) {
  const r = results[i].json || {};
  const b = (recips[i] && recips[i].json) || {};
  const row = { contactId: b.contactId, name: b.name, phone: b.phone, tier: b.tier };
  if (r.messageId || r.conversationId || r.success === true) { row.messageId = r.messageId || ''; sent.push(row); }
  else {
    // 2026-08-26: this was String(r.message || ...), and GHL returns `message`
    // as an OBJECT on failure, so every failed send recorded the literal text
    // '[object Object]'. Angel Alberto's text failed with a 401 'Command timed
    // out' - GHL throttling wearing an auth error's clothes - and the report
    // said nothing at all. Serialise anything that is not already a string.
    const say = (v) => v == null ? ''
      : (typeof v === 'string' ? v
      : (v.message && typeof v.message === 'string' ? v.message : JSON.stringify(v)));
    row.error = (say(r.error) || say(r.message) || JSON.stringify(r) || 'unknown').slice(0, 300);
    failed.push(row);
  }
}

return [{ json: {
  address: (recips[0] && recips[0].json.address) || '',
  recordId: (recips[0] && recips[0].json.recordId) || null,
  eligible: stats.eligible,
  attempted: results.length,
  sent: sent.length,
  failed: failed.length,
  held_by_limit: stats.heldByLimit,
  sent_rows: sent,
  failed_rows: failed,
  skipped_rows: stats.skipped
} }];

const t = $('Tally Sends').first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = (a, extra) => {
  if (!a || !a.length) return '<p>None.</p>';
  let h = '<table><tr><th>Buyer</th><th>Tier</th><th>Phone</th>' + (extra ? '<th>' + extra + '</th>' : '') + '</tr>';
  for (const b of a) h += '<tr><td>' + esc(b.name) + '</td><td>' + esc(b.tier) + '</td><td>' + esc(b.phone || '') + '</td>' + (extra ? '<td>' + esc(b.why || b.error || '') + '</td>' : '') + '</tr>';
  return h + '</table>';
};
const H = [];
H.push('<h1>' + esc(t.sent) + ' text message(s) sent</h1>');
H.push('<p>Deal: ' + esc(t.address) + '</p>');
H.push('<table><tr><th>Eligible after exclusions</th><td><b>' + esc(t.eligible) + '</b></td></tr>' +
       '<tr><th>Attempted</th><td>' + esc(t.attempted) + '</td></tr>' +
       '<tr><th>Sent</th><td><b>' + esc(t.sent) + '</b></td></tr>' +
       '<tr><th>Failed</th><td>' + esc(t.failed) + '</td></tr>' +
       '<tr><th>Held back by your limit</th><td>' + esc(t.held_by_limit) + '</td></tr></table>');
if ($('Guard Rails').first().json.teaserEdited) H.push('<p><b>Note:</b> you edited the teaser before sending. The deal record has been updated to match what actually went out.</p>');
let oppNote = '';
try {
  const b = $('Build Buyer Interest Opps').all();
  const made = b.filter(x => x.json && x.json.opp).length;
  if (made) oppNote = '<p><b>' + made + '</b> Buyer Interest opportunit(ies) created at stage <b>' +
    esc(b[0].json._stageName) + '</b>. Open the Buyer Interest pipeline and search this address to see every buyer tied to this deal.</p>';
} catch (e) {}
if (oppNote) H.push(oppNote);
H.push('<h2>Sent to</h2>'); H.push(rows(t.sent_rows));
H.push('<h2>Failed</h2>'); H.push(rows(t.failed_rows, 'Error'));
H.push('<h2>Not sent - excluded or suppressed</h2>'); H.push(rows(t.skipped_rows, 'Reason'));
return [{ json: { summary_html: H.join('') } }];

const d = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const msg = d.abort || 'No eligible buyers for this deal - every match was excluded or suppressed.';
return [{ json: { summary_html: '<h1>Nothing was sent</h1><p>' + esc(msg) + '</p>' } }];

