parameters.jsCode:
// One Buyer Interest opportunity per buyer on the recipient list, created
// BEFORE the teaser goes out.
//
// 2026-08-26: this used to run last, after every text and every engagement
// write. A buyer who replied during the send had no card and no
// buy_last_deal, so the reply handler could not tell which deal they meant
// and held them for a human - it failed hardest on the fastest buyers.
// The handler resolves the deal as `matched || reachedOut[0]`, so a card
// that already exists answers the question on its own.
//
// The trade: the send has not happened yet, so cards can no longer be
// filtered to buyers who actually received it. A failed send leaves a card
// for someone never texted. The summary reports that count.
// This is the durable buyer<->deal association: open the Buyer Interest
// pipeline, search the address, and every buyer tied to that deal is listed
// with the stage they reached. Contact fields can't express this - a buyer
// belongs to many deals over time.
const pipes = ($input.first().json.pipelines) || [];
const bi = pipes.find(p => (p.name || '').toLowerCase().indexOf('buyer interest') !== -1);

const recips = $('Build Recipient List').all();
// Same source Tally Sends used for it; every recipient row carries the deal.
const dealAddress = (recips[0] && recips[0].json.address) || '';

if (!bi || !bi.stages || !bi.stages.length) {
  return [{ json: { _skip: true, reason: 'Buyer Interest pipeline not found' } }];
}

// Prefer a stage that honestly means "we texted them"; otherwise fall back to
// the first stage. Renaming/adding a stage in GHL needs no code change.
const wanted = ['reached out', 'texted', 'sent', 'blasted', 'contacted'];
let stage = bi.stages.find(s => wanted.indexOf((s.name || '').toLowerCase()) !== -1);
if (!stage) stage = bi.stages[0];


// The same labels the review page shows, so the pipeline filter and the
// console agree on what a segment is called.
const SEG_LABEL = { warm: 'Warm list', geo_cold: 'InvestorBase Matched',
                    general_cold: 'General cold' };
const out = [];
for (const r of recips) {
  const b = r.json;
  if (!b || !b.contactId) continue;
  out.push({ json: {
    opp: {
      pipelineId: bi.id,
      locationId: 'ib5jEnyqqq06FIEqlVGs',
      // Buyer first: the pipeline card shows the name, and with several deals
      // running the address is what you filter on, not what you read.
      name: b.name + ' — ' + (dealAddress || 'Deal'),
      // Opportunity custom fields use fieldValue; CONTACT custom fields use
      // value. Same API, different key. Getting it wrong fails silently.
      // The opportunity carries a COPY of who this buyer is, because GHL's
      // opportunity search cannot filter on a contact's fields - only on
      // pipeline, stage, status, assignee and a single contactId. Without
      // these you cannot ask 'show me the VIPs on 580 SE 6th', which is the
      // question a dispo manager actually has.
      // Copied at send time on purpose: it records what was true when we
      // texted them, not what is true today.
      customFields: [
        { id: '23Qr6cqR1IP1zFknf5Wn', fieldValue: dealAddress || '' },   // opp_deal_address
        { id: '9teeY5fWTPptnVygRVae', fieldValue: b.tier && b.tier !== '(none)' ? b.tier : '' },
        { id: 'hJ06opXeHtm3nt072Wog', fieldValue: b.source || '' },
        { id: 'hLc4zz9NtnpjwlCQERMV', fieldValue: SEG_LABEL[b.segment] || '' },
      ],
      pipelineStageId: stage.id,
      status: 'open',
      contactId: b.contactId
    },
    _stageName: stage.name
  } });
}

if (!out.length) return [{ json: { _skip: true, reason: 'no recipients' } }];
return out;

// JSON result for the Dispo Deal Console's send button.
const t = $('Tally Sends').first().json;

let opps = 0, oppsFailed = 0, stage = '';
try {
  const b = $('Build Buyer Interest Opps').all();
  if (b.length && b[0].json) stage = b[0].json._stageName || '';
} catch (e) {}
try {
  // Count the CREATE node's responses, not the items we queued for it. Counting
  // the built items reported 166 opportunities on a blast that created 126 -
  // the same mistake already fixed one function down for engagementWrites.
  const made = $('Create Buyer Interest Opps').all();
  opps = made.filter(x => x.json && !x.json.error && (x.json.opportunity || x.json.id)).length;
  oppsFailed = made.filter(x => x.json && x.json.error).length;
} catch (e) { opps = 0; }

const bits = [];
bits.push(t.sent + ' teaser' + (t.sent === 1 ? '' : 's') + ' sent.');
if (t.failed) bits.push(t.failed + ' failed.');
if (oppsFailed) bits.push(oppsFailed + ' opportunit' + (oppsFailed === 1 ? 'y' : 'ies') +
  ' could not be created (the texts still went).');
if (opps) bits.push(opps + ' Buyer Interest opportunit' + (opps === 1 ? 'y' : 'ies') +
                    ' created at "' + stage + '" — open the pipeline and search this address.');
else bits.push('Track replies in the Buyer Interest pipeline.');

let engagementWrites = 0;
// Count what the WRITE node actually returned, not what we queued for it.
// Counting the built items reported engagementWrites:1 while an IF quietly
// routed every one of them down the false branch and nothing was written.
try {
  engagementWrites = $('Write Engagement to Buyers').all()
    .filter(x => x.json && !x.json.error && (x.json.contact || x.json.id || x.json.succeded)).length;
} catch (e) { engagementWrites = 0; }

return [{ json: {
  ok: true,
  engagementWrites,
  queued: t.sent,
  failed: t.failed,
  eligible: t.eligible,
  opportunities: opps,
  opportunitiesFailed: oppsFailed,
  message: bits.join(' '),
  failed_rows: t.failed_rows
} }];

// The run aborted before anything sent. Report it as a failure so the console
// shows the red "did not go out" banner rather than a green success box.
const g = $('Guard Rails').first().json;
return [{ json: { ok: false, error: g.abort || 'Aborted before sending.', queued: 0 } }];

// One update per buyer who ACTUALLY received the text.
//
// Everything here is written at the only moment it can be known. A field
// nobody populates is worse than no field: the smart list still exists, returns
// nonsense, and gets trusted anyway.
const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID = {};
for (const d of defs) ID[d.name] = d.id;

const tally = $('Tally Sends').first().json;
const recips = $('Build Recipient List').all().map(r => r.json);
const byId = {};
for (const r of recips) if (r && r.contactId) byId[r.contactId] = r;

const nowIso = new Date().toISOString();
const address = tally.address || '';

// The opener only - the whole teaser would blow past the field and the point is
// to know which hook a buyer has already seen so it is not reused on them.
const opener = (t) => {
  const first = String(t || '').split(/(?<=[.!?])\s+/)[0] || String(t || '');
  return first.slice(0, 240);
};

const out = [];
for (const row of (tally.sent_rows || [])) {
  const id = row.contactId;
  if (!id) continue;
  const r = byId[id] || {};

  const cf = [];
  const put = (name, value) => { if (ID[name]) cf.push({ id: ID[name], value }); };

  put('buy_last_contacted', nowIso);
  put('buy_last_deal', address);
  // smsBody, not teaser: the teaser still carries the raw {{first_name}}
  // token. This field exists so the generator does not reuse an opener on
  // someone, which means it has to hold what the buyer actually READ.
  put('buy_last_hook', opener(r.smsBody || r.teaser));
  put('buy_deals_sent', Number(r.priorDealsSent || 0) + 1);
  // Set-once, like first_contacted: the whole point is that this buyer keeps
  // seeing the same number. Re-stamping on every blast would let a later rule
  // change silently move an established buyer to a different line.
  if (r.fromNumberIsNew && r.fromNumber) put('buy_from_number', r.fromNumber);

  // Set once, never updated - it is the buyer's tenure with us.
  if (!r.priorFirstContacted) put('buy_first_contacted', nowIso);

  if (!cf.length) continue;
  out.push({ json: { contactId: id, name: row.name, body: { customFields: cf } } });
}

// Nothing sent, or no field ids resolved. Pass a marker through rather than
// stalling the branch - the opportunities still need to be created.
if (!out.length) return [{ json: { _skip: true, reason: (tally.sent_rows || []).length ? 'no field ids resolved' : 'nothing sent' } }];
return out;

// Card creation is a detour. The blast must keep sending to the recipient
// list built earlier, not to whatever the opportunity API just returned.
return $('Build Recipient List').all();
